function(container, apiUrl, tables) {
  // 業務ロジックモジュールのインポート
  const { 
    collectSalesData, 
    classifySalesDataByProduct, 
    classifySalesDataByStore, 
    filterValidProductData,
    collectWeatherData,
    collectEventData,
    collectSeasonalData,
    analyzeCorrelationSalesWeather,
    analyzeCorrelationSalesEvent,
    analyzeCorrelationSalesSeason,
    compareWithHistoricalData,
    findAlternativeComparisonData,
    validateComparisonPeriod
  } = window.aivicLogic || {};

  // テーブルインデックス定義
  const STORES_TABLE = 1; // 店舗マスタ
  const PRODUCTS_TABLE = 2; // 商品マスタ
  const FORECAST_TABLE = 9; // 需要予測結果
  const ORDERS_TABLE = 10; // 発注データ

  let currentForecastData = [];
  let storesData = [];
  let productsData = [];

  // 今日の日付を設定
  const today = new Date().toISOString().split('T')[0];
  const orderDateInput = container.querySelector('#order-date');
  if (orderDateInput) {
    orderDateInput.value = today;
  }

  // 納期予定日を3日後に設定
  const deliveryDate = new Date();
  deliveryDate.setDate(deliveryDate.getDate() + 3);
  const deliveryDateInput = container.querySelector('#delivery-date');
  if (deliveryDateInput) {
    deliveryDateInput.value = deliveryDate.toISOString().split('T')[0];
  }

  // エラー表示関数
  function showError(message) {
    if (window.aivicNotify && window.aivicNotify.error) {
      window.aivicNotify.error(message);
    } else {
      const errorDiv = container.querySelector('#error-message');
      if (errorDiv) {
        errorDiv.textContent = message;
        errorDiv.classList.remove('hidden');
        setTimeout(() => errorDiv.classList.add('hidden'), 5000);
      }
    }
  }

  // 成功メッセージ表示関数
  function showSuccess(message) {
    if (window.aivicNotify && window.aivicNotify.success) {
      window.aivicNotify.success(message);
    }
  }

  // 合計金額計算・表示
  function updateTotalAmount() {
    let total = 0;
    container.querySelectorAll('.order-quantity-input').forEach(input => {
      const quantity = parseInt(input.value) || 0;
      const price = parseInt(input.dataset.price) || 0;
      total += quantity * price;
    });
    const totalAmountElement = container.querySelector('#total-amount');
    if (totalAmountElement) {
      totalAmountElement.textContent = '¥' + total.toLocaleString();
    }
  }

  // 発注数量入力フィールドのイベントハンドラ
  function setupQuantityInput(input) {
    input.addEventListener('input', function() {
      const quantity = parseInt(this.value) || 0;
      const price = parseInt(this.dataset.price) || 0;
      const amountCell = this.closest('tr').querySelector('.order-amount');
      if (amountCell) {
        amountCell.textContent = '¥' + (quantity * price).toLocaleString();
      }
      updateTotalAmount();
    });

    input.addEventListener('blur', function() {
      // 数値バリデーション
      const value = this.value.trim();
      if (value !== '' && (isNaN(value) || parseInt(value) < 0)) {
        showError('発注数量は0以上の数値を入力してください');
        this.focus();
      }
    });
  }

  // 需要予測結果テーブル描画
  function renderForecastTable(forecastData) {
    const tbody = container.querySelector('#forecast-table tbody');
    if (!tbody) return;

    tbody.innerHTML = '';

    forecastData.forEach(item => {
      const product = productsData.find(p => p.id === item.product_id);
      const store = storesData.find(s => s.id === item.store_id);

      const row = document.createElement('tr');
      row.innerHTML = `
        <td>${store ? store.name : '不明'}</td>
        <td>${product ? product.name : '不明'}</td>
        <td>${item.forecast_quantity || 0}</td>
        <td>${item.current_stock || 0}</td>
        <td>${Math.max(0, (item.forecast_quantity || 0) - (item.current_stock || 0))}</td>
        <td>¥${(product ? product.price : 0).toLocaleString()}</td>
        <td>
          <input type="number" 
                 class="order-quantity-input" 
                 min="0" 
                 value="${Math.max(0, (item.forecast_quantity || 0) - (item.current_stock || 0))}"
                 data-product-id="${item.product_id}"
                 data-store-id="${item.store_id}"
                 data-price="${product ? product.price : 0}">
        </td>
        <td class="order-amount">¥${(Math.max(0, (item.forecast_quantity || 0) - (item.current_stock || 0)) * (product ? product.price : 0)).toLocaleString()}</td>
      `;
      tbody.appendChild(row);

      // 数量入力フィールドにイベントハンドラを設定
      const quantityInput = row.querySelector('.order-quantity-input');
      setupQuantityInput(quantityInput);
    });

    updateTotalAmount();
  }

  // 需要予測データ読み込み
  async function loadForecastData() {
    try {
      const storeId = container.querySelector('#store-select')?.value;
      const targetDate = container.querySelector('#target-date')?.value;

      if (!storeId || !targetDate) {
        showError('店舗と対象日を選択してください');
        return;
      }

      // 需要予測結果を取得
      const forecastResponse = await window.aivicApi.list(tables[FORECAST_TABLE], {
        store_id: storeId,
        target_date: targetDate
      });

      if (forecastResponse.success) {
        currentForecastData = forecastResponse.data || [];
        renderForecastTable(currentForecastData);

        if (currentForecastData.length === 0) {
          showError('指定された条件の需要予測データが見つかりません');
        }
      } else {
        showError('需要予測データの取得に失敗しました');
      }
    } catch (error) {
      console.error('需要予測データ読み込みエラー:', error);
      showError('需要予測データの読み込み中にエラーが発生しました');
    }
  }

  // 発注実行
  async function executeOrder() {
    try {
      const orderDate = container.querySelector('#order-date')?.value;
      const deliveryDate = container.querySelector('#delivery-date')?.value;
      const storeId = container.querySelector('#store-select')?.value;

      if (!orderDate || !deliveryDate || !storeId) {
        showError('発注日、納期予定日、店舗を入力してください');
        return;
      }

      // 発注数量を収集
      const orderItems = [];
      container.querySelectorAll('.order-quantity-input').forEach(input => {
        const quantity = parseInt(input.value) || 0;
        if (quantity > 0) {
          orderItems.push({
            product_id: input.dataset.productId,
            store_id: input.dataset.storeId,
            quantity: quantity,
            unit_price: parseInt(input.dataset.price) || 0,
            total_amount: quantity * (parseInt(input.dataset.price) || 0)
          });
        }
      });

      if (orderItems.length === 0) {
        showError('発注する商品がありません');
        return;
      }

      // 発注データを保存
      const orderData = {
        order_date: orderDate,
        delivery_date: deliveryDate,
        store_id: storeId,
        total_amount: orderItems.reduce((sum, item) => sum + item.total_amount, 0),
        status: '発注済み',
        items: orderItems
      };

      const saveResponse = await window.aivicApi.save(tables[ORDERS_TABLE], orderData);

      if (saveResponse.success) {
        showSuccess('発注が完了しました');

        // 発注完了後、テーブルをクリア
        const tbody = container.querySelector('#forecast-table tbody');
        if (tbody) {
          tbody.innerHTML = '';
        }

        // 合計金額をリセット
        const totalAmountElement = container.querySelector('#total-amount');
        if (totalAmountElement) {
          totalAmountElement.textContent = '¥0';
        }

        // フォームをリセット
        const targetDateInput = container.querySelector('#target-date');
        if (targetDateInput) {
          targetDateInput.value = '';
        }

      } else {
        showError('発注の保存に失敗しました');
      }
    } catch (error) {
      console.error('発注実行エラー:', error);
      showError('発注処理中にエラーが発生しました');
    }
  }

  // 初期データ読み込み
  async function loadInitialData() {
    try {
      // 店舗データ読み込み
      const storesResponse = await window.aivicApi.list(tables[STORES_TABLE]);
      if (storesResponse.success) {
        storesData = storesResponse.data || [];

        // 店舗選択肢を設定
        const storeSelect = container.querySelector('#store-select');
        if (storeSelect) {
          storeSelect.innerHTML = '<option value="">店舗を選択</option>';
          storesData.forEach(store => {
            const option = document.createElement('option');
            option.value = store.id;
            option.textContent = store.name;
            storeSelect.appendChild(option);
          });
        }
      }

      // 商品データ読み込み
      const productsResponse = await window.aivicApi.list(tables[PRODUCTS_TABLE]);
      if (productsResponse.success) {
        productsData = productsResponse.data || [];
      }
    } catch (error) {
      console.error('初期データ読み込みエラー:', error);
      showError('初期データの読み込み中にエラーが発生しました');
    }
  }

  // イベントハンドラ設定
  function setupEventHandlers() {
    // 予測データ読み込みボタン
    const loadForecastBtn = container.querySelector('#load-forecast-btn');
    if (loadForecastBtn) {
      loadForecastBtn.addEventListener('click', loadForecastData);
    }

    // 発注実行ボタン
    const executeOrderBtn = container.querySelector('#execute-order-btn');
    if (executeOrderBtn) {
      executeOrderBtn.addEventListener('click', executeOrder);
    }

    // 店舗選択変更時
    const storeSelect = container.querySelector('#store-select');
    if (storeSelect) {
      storeSelect.addEventListener('change', function() {
        // 店舗変更時はテーブルをクリア
        const tbody = container.querySelector('#forecast-table tbody');
        if (tbody) {
          tbody.innerHTML = '';
        }
        const totalAmountElement = container.querySelector('#total-amount');
        if (totalAmountElement) {
          totalAmountElement.textContent = '¥0';
        }
      });
    }

    // 対象日変更時
    const targetDateInput = container.querySelector('#target-date');
    if (targetDateInput) {
      targetDateInput.addEventListener('change', function() {
        // 日付変更時はテーブルをクリア
        const tbody = container.querySelector('#forecast-table tbody');
        if (tbody) {
          tbody.innerHTML = '';
        }
        const totalAmountElement = container.querySelector('#total-amount');
        if (totalAmountElement) {
          totalAmountElement.textContent = '¥0';
        }
      });
    }
  }

  // 初期化実行
  loadInitialData();
  setupEventHandlers();
}
